// operationOptions are the stamps an operation's write of the row sets, none
// on a table with no updatedAt or updatedBy, and the preconditions
// WithPreconditions names, which its command presents (D104).
func (r *AccountRepository) operationOptions(ctx context.Context) *rules.ExecuteOptions {
	return &rules.ExecuteOptions{Preconditions: behaviorPreconditions(ctx)}
}

// createThroughCore is CreateOne on the repository's transaction: input's row
// stamped, created by the behaviors' core, whose uses initialize the fields
// they own, with the columns the insert writes, and read back.
func (r *AccountRepository) createThroughCore(ctx context.Context, input *AccountCreate) (*types.Account, error) {
	row := input.row()
	columns, err := r.createColumns(row)
	if err != nil {
		return nil, err
	}
	opts := &rules.CreateOptions{ID: r.createKey(row), ExecuteOptions: rules.ExecuteOptions{OwnColumns: columns, Preconditions: behaviorPreconditions(ctx)}}
	key, err := rules.RunCreate(ctx, rulesHost(r.tx), "Account", r.coreOwn(row), behaviorCaller(ctx), opts)
	if err != nil {
		return nil, err
	}
	id, err := types.ParseIdentityUUID(key)
	if err != nil {
		return nil, fmt.Errorf("create Account: the core's key %q: %w", key, err)
	}
	return r.GetOne(ctx, id, nil)
}

// upsertInputs are inputs as an upsert inserts them (D103): each one's row
// with the fields its behaviors own as the core's create of it gives them,
// run to its change set and not applied, so the insert writes what CreateOne
// would have, and the update, which sets none of them, leaves them as the
// row holds them. A refusal of the core's is returned before anything is
// written.
func (r *AccountRepository) upsertInputs(ctx context.Context, inputs []*AccountCreate) ([]*types.Account, error) {
	host := rulesHost(r.tx)
	rows := make([]*types.Account, 0, len(inputs))
	for _, input := range inputs {
		row := input.row()
		owned, err := rules.PrepareCreate(ctx, host, "Account", r.coreOwn(row), behaviorCaller(ctx), &rules.CreateOptions{ID: r.createKey(row), ExecuteOptions: rules.ExecuteOptions{Preconditions: behaviorPreconditions(ctx)}})
		if err != nil {
			return nil, err
		}
		if value, ok := owned["status"]["status"]; ok {
			if err := json.Unmarshal(value, &row.Status); err != nil {
				return nil, fmt.Errorf("upsert Account: the core's status.status %s: %w", value, err)
			}
		}
		if at, err := rules.TimeOfMillis(owned["status"]["enteredAt"]); err != nil {
			return nil, fmt.Errorf("upsert Account: the core's status.enteredAt: %w", err)
		} else if at != nil {
			value := types.TemporalDateTime(*at)
			row.StatusEnteredAt = &value
		}
		rows = append(rows, row)
	}
	return rows, nil
}

// Allowed fields for Account (for validation and ordering)
var AccountAllowedFields = map[string]bool{
	"id":                true,
	"name":              true,
	"status":            true,
	"status_entered_at": true,
	"_version":          true,
	"workspace_id":      true,
}

// Quoted field names for Account (for SQL generation)
var AccountQuotedFields = map[string]string{
	"id":                `id`,
	"name":              `"name"`,
	"status":            `status`,
	"status_entered_at": `status_entered_at`,
	"_version":          `_version`,
	"workspace_id":      `workspace_id`,
}

// accountSortColumns are the columns of Account's sort fields, by
// field, as FindPage's ORDER BY and keyset write them: qualified by the table,
// and by page_key, the alias of the subquery that reads the key's row. They
// are the only text of a sort that reaches its SQL (D60, amended).
var accountSortColumns = map[AccountSortField]struct{ sql, key string }{
	AccountSortById:     {`account.id`, `page_key.id`},
	AccountSortByName:   {`account."name"`, `page_key."name"`},
	AccountSortByStatus: {`account.status`, `page_key.status`},
}

// buildAccountOrderByClause builds an ORDER BY clause for Account.
// quotedTable is the table's name as the FROM clause spells it, quoted when
// it is a keyword (a table named order is "order").
func buildAccountOrderByClause(orderBy []AccountOrderBy, quotedTable string) string {
	if len(orderBy) == 0 {
		return ""
	}

	var clauses []string
	for _, order := range orderBy {
		fieldStr := string(order.Field)
		direction := "ASC"
		if order.Desc {
			direction = "DESC"
		}
		// Use pre-computed quoted field name
		quotedField, ok := AccountQuotedFields[fieldStr]
		if !ok {
			quotedField = fieldStr // Fallback to unquoted if not found
		}
		clauses = append(clauses, fmt.Sprintf("%s.%s %s", quotedTable, quotedField, direction))
	}

	if len(clauses) == 0 {
		return ""
	}

	return " ORDER BY " + strings.Join(clauses, ", ")
}

func accountUUIDValue(value any) (types.IdentityUUID, bool) {
	switch v := value.(type) {
	case types.IdentityUUID:
		return v, true
	case *types.IdentityUUID:
		if v == nil {
			var zero types.IdentityUUID
			return zero, false
		}
		return *v, true
	default:
		var zero types.IdentityUUID
		return zero, false
	}
}

func accountUUIDPtr(value types.IdentityUUID) *types.IdentityUUID {
	return &value
}

// batchWorkspaceByIDs fetches multiple Workspace records by their IDs using a single query.
//
// This is the recursion point: the FindMany below hydrates Workspace's own
// relations, which lands back here for each of them. enterRelationHydration is
// what bounds that -- see the guard's contract in utils.go. defaultSelection
// says whether the caller named a nested selection or fell back to
// WorkspaceFields{}.All(); only the fallback is pruned.
//
// A refusal returns no rows rather than an error, because the caller's miss
// path already writes the id-only stub that a refused expansion should produce.
func (r *AccountRepository) batchWorkspaceByIDs(ctx context.Context, ids []types.IdentityUUID, opts *WorkspaceFindOptions, defaultSelection bool) (map[types.IdentityUUID]*types.Workspace, error) {
	if len(ids) == 0 {
		return map[types.IdentityUUID]*types.Workspace{}, nil
	}

	ctx, allowed := enterRelationHydration(ctx, "Account", "workspace", "Workspace", defaultSelection)
	if !allowed {
		return map[types.IdentityUUID]*types.Workspace{}, nil
	}

	// Get repository for related type
	var repo *WorkspaceRepository
	if r.tx != nil {
		txDB := r.txDB
		if txDB == nil {
			txDB = r.db
		}
		repo = &WorkspaceRepository{tx: r.tx, txDB: txDB}
	} else if r.db != nil {
		repo = r.db.Workspace
	} else if r.txDB != nil {
		repo = r.txDB.Workspace
	} else {
		return nil, fmt.Errorf("no database connection available for batch fetch")
	}

	findOpts := opts
	if findOpts == nil || findOpts.Fields.IsZero() {
		findOpts = &WorkspaceFindOptions{
			Fields: (WorkspaceFields{}).All(),
		}
	} else {
		optsCopy := *findOpts
		findOpts = &optsCopy
	}

	if findOpts.Limit <= 0 || findOpts.Limit < len(ids) {
		findOpts.Limit = len(ids)
	}

	relatedRecords, err := repo.findRelated(
		ctx,
		&WorkspaceFilter{
			Id: &UUIDFilter{
				In: ids,
			},
		},
		findOpts,
	)
	if err != nil {
		return nil, err
	}

	relatedByID := make(map[types.IdentityUUID]*types.Workspace, len(relatedRecords))
	for _, related := range relatedRecords {
		if related == nil {
			continue
		}
		relatedID, ok := accountUUIDValue(related.Id)
		if !ok {
			continue
		}
		relatedByID[relatedID] = related
	}

	return relatedByID, nil
}

// GetOne retrieves a single Account by ID
func (r *AccountRepository) GetOne(ctx context.Context, id types.IdentityUUID, opts *AccountGetOptions) (*types.Account, error) {
	// Determine if we're using partial field selection
	var fieldStrings []string
	usePartialFields := opts != nil && !opts.Fields.IsZero()

	// Build query - if no fields specified, select all in scan order
	var query string
	if usePartialFields {
		// Build selected fields in OrderedMembers order so FK columns match scan order.
		if opts.Fields.Id {
			fieldStrings = append(fieldStrings, "id")
		}
		if opts.Fields.Name {
			fieldStrings = append(fieldStrings, "name")
		}
		if opts.Fields.Workspace || !opts.Fields.WorkspaceNested.IsZero() {
			fieldStrings = append(fieldStrings, "workspace_id")
		}
		if opts.Fields.Status {
			fieldStrings = append(fieldStrings, "status")
		}
		if opts.Fields.StatusEnteredAt {
			fieldStrings = append(fieldStrings, "status_entered_at")
		}
		if opts.Fields.Version {
			fieldStrings = append(fieldStrings, "_version")
		}
		// Validate fields
		if err := validateFields(fieldStrings, AccountAllowedFields); err != nil {
			return nil, err
		}
		selectFields := buildSelectFieldsTyped(fieldStrings, "account")
		query = fmt.Sprintf(`SELECT %s FROM account WHERE id = $1`, selectFields)
	} else {
		// Select all fields in explicit order matching scan order (using OrderedMembers for schema order)
		query = `SELECT "id", "name", "workspace_id", "status", "status_entered_at", "_version" FROM account WHERE id = $1`
	}

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, id.ToUUID())
	} else {
		row = r.db.pool.QueryRow(ctx, query, id.ToUUID())
	}

	// Scan result - when selecting all fields, scan directly into struct
	result := &types.Account{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempStatusEnteredAt *types.TemporalDateTime

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)
	var tempRelWorkspace *types.IdentityUUID
	var selectedRelWorkspace bool

	var err error
	if usePartialFields {
		// Dynamic scanning for partial field selection
		// Track whether special fields were selected so we can post-process after Scan.

		var selectedStatusEnteredAt bool

		scanDest := make([]any, len(fieldStrings))
		for i, fieldName := range fieldStrings {
			switch fieldName {
			case "id":
				scanDest[i] = &result.Id
			case "name":
				scanDest[i] = &result.Name
			case "status":
				scanDest[i] = &result.Status
			case "status_entered_at":
				scanDest[i] = &tempStatusEnteredAt
				selectedStatusEnteredAt = true
			case "_version":
				scanDest[i] = &result.Version
			case "workspace_id":
				scanDest[i] = &tempRelWorkspace
				selectedRelWorkspace = true
			default:
				return nil, fmt.Errorf("unexpected field %q for Account.GetOne", fieldName)
			}
		}

		err = row.Scan(scanDest...)
		if err == nil {
			// Copy nullable fields when present
			var jsonFieldDecodeErr error

			if selectedStatusEnteredAt && tempStatusEnteredAt != nil {
				// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
				result.StatusEnteredAt = tempStatusEnteredAt
			}
			if jsonFieldDecodeErr != nil {
				return nil, jsonFieldDecodeErr
			}
		}
	} else {
		selectedRelWorkspace = true

		// Scan all fields in schema order (matches DDL column order)
		err = row.Scan(

			&result.Id,

			&result.Name,

			&tempRelWorkspace,

			&result.Status,

			&tempStatusEnteredAt,

			&result.Version,
		)

		if err == nil {
			// Copy nullable fields when present

			if tempStatusEnteredAt != nil {
				// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
				result.StatusEnteredAt = tempStatusEnteredAt
			}
		}
	}

	if err != nil {
		if err == pgx.ErrNoRows {
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("failed to scan row: %w", err)
	}

	// Hydrate relationship foreign keys into nested objects from typed field selections.
	if selectedRelWorkspace && tempRelWorkspace != nil {
		relRequested := opts != nil && (opts.Fields.Workspace || !opts.Fields.WorkspaceNested.IsZero())
		if relRequested {
			childFields := (WorkspaceFields{}).All()
			childFieldsAreDefault := true
			if !opts.Fields.WorkspaceNested.IsZero() {
				childFields = opts.Fields.WorkspaceNested
				childFieldsAreDefault = false
			}

			relMap, err := r.batchWorkspaceByIDs(ctx, []types.IdentityUUID{*tempRelWorkspace}, &WorkspaceFindOptions{
				Fields: childFields,
				Limit:  1,
			}, childFieldsAreDefault)
			if err != nil {
				return nil, fmt.Errorf("failed to fetch workspace: %w", err)
			}
			if rel, ok := relMap[*tempRelWorkspace]; ok {
				result.Workspace = *rel
			} else {
				// Preserve FK ID even when entity not found (e.g. soft-deleted)
				result.Workspace.Id = accountUUIDPtr(*tempRelWorkspace)
			}
		} else {
			// Just set the ID when not including full entity
			result.Workspace.Id = accountUUIDPtr(*tempRelWorkspace)
		}
	}

	return result, nil
}

// GetManyByIDs retrieves multiple Account records by their IDs in a single query
func (r *AccountRepository) GetManyByIDs(ctx context.Context, ids []types.IdentityUUID) (map[types.IdentityUUID]*types.Account, error) {
	if len(ids) == 0 {
		return map[types.IdentityUUID]*types.Account{}, nil
	}

	// Dedupe IDs
	seen := make(map[types.IdentityUUID]bool)
	uniqueIDs := make([]types.IdentityUUID, 0, len(ids))
	for _, id := range ids {
		if !seen[id] {
			seen[id] = true
			uniqueIDs = append(uniqueIDs, id)
		}
	}

	// Build WHERE id IN (...) clause
	placeholders := make([]string, len(uniqueIDs))
	args := make([]interface{}, len(uniqueIDs))
	for i, id := range uniqueIDs {
		placeholders[i] = fmt.Sprintf("$%d", i+1)
		args[i] = id.ToUUID()
	}

	// Build query with explicit column order
	query := fmt.Sprintf(`SELECT "id", "name", "workspace_id", "status", "status_entered_at", "_version" FROM account WHERE id IN (%s)`, strings.Join(placeholders, ", "))

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results into map
	resultMap := make(map[types.IdentityUUID]*types.Account, len(uniqueIDs))
	for rows.Next() {
		entity := &types.Account{}

		// Create temporary variables for nullable fields that need pointer scanning

		var tempStatusEnteredAt *types.TemporalDateTime

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)
		var tempRelWorkspace *types.IdentityUUID

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&entity.Id,

			&entity.Name,

			&tempRelWorkspace,

			&entity.Status,

			&tempStatusEnteredAt,

			&entity.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present

		if tempStatusEnteredAt != nil {
			entity.StatusEnteredAt = tempStatusEnteredAt
		}

		// Set relationship IDs from scanned FK values
		if tempRelWorkspace != nil {
			entity.Workspace.Id = accountUUIDPtr(*tempRelWorkspace)
		}

		entityID, ok := accountUUIDValue(entity.Id)
		if !ok {
			continue
		}
		resultMap[entityID] = entity
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	return resultMap, nil
}

